def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_def = sum(1 for a, b in history if b == 'D')
    opp_c = n - opp_def
    opp_rate = opp_c / n

    if opp_rate < 0.3:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        if opp_rate > 0.6:
            return 'C'
        recent = history[-5:] if n >= 5 else history
        recent_def = sum(1 for a, b in recent if b == 'D')
        if recent_def >= 2:
            return 'D'
        return 'C' if rng.random() < 0.5 else 'D'

    my_def = sum(1 for a, b in history if a == 'D')
    if my_def > opp_def + 2:
        return 'C'

    return 'C'
